subsection.md:
\begin{array}{c|c|c}
\text{Degree} \amp \text{Kind of form} \amp \text{Where it is integrated} \\ \hline
0 \amp \text{function} \amp \text{oriented points}\\[1mm]
1 \amp \text{line-measuring form} \amp \text{oriented curves}\\[1mm]
2 \amp \text{area-measuring form} \amp \text{oriented surfaces}\\[1mm]
3 \amp \text{volume-measuring form} \amp \text{oriented solids}
\end{array}

image.asymptote:
import three;
size(15cm);
currentprojection=orthographic(8,-13,9);
pen edge=gray(0.30)+linewidth(0.8pt);
pen blue=rgb(0.12,0.38,0.73)+linewidth(1.4pt);
dot((-5.9,0,0),rgb(0.15,0.35,0.68)+4pt);
label("point",(-5.9,0,-0.6),S);
label("$0$-form",(-5.9,0,-1.15),S);
path3 curve=(-3.7,-0.6,0)..controls(-3.2,0.5,0.5) and (-2.5,-0.5,0.8)..(-1.8,0.6,0.3);
draw(curve,blue,Arrow3);
label("curve",(-2.7,0,-0.6),S);
label("$1$-form",(-2.7,0,-1.15),S);
triple A=(0.3,-0.7,0), B=(2.3,-0.7,0.35), C=(2.7,0.8,0.9), D=(0.7,0.8,0.55);
draw(surface(A--B--C--D--cycle),rgb(0.54,0.37,0.70)+opacity(0.42));
draw(A--B--C--D--cycle,edge);
draw(A--B,blue,Arrow3);
draw(A--D,blue,Arrow3);
label("surface patch",(1.5,0,-0.7),S);
label("$2$-form",(1.5,0,-1.2),S);
triple P=(4.8,-0.6,0), Q=(6.4,-0.6,0), R=(6.4,0.8,0), S=(4.8,0.8,0);
triple T=(4.8,-0.6,1.45), U=(6.4,-0.6,1.45), V=(6.4,0.8,1.45), W=(4.8,0.8,1.45);
draw(surface(P--Q--U--T--cycle),rgb(0.75,0.54,0.26)+opacity(0.35));
draw(surface(Q--R--V--U--cycle),rgb(0.75,0.54,0.26)+opacity(0.35));
draw(surface(T--U--V--W--cycle),rgb(0.75,0.54,0.26)+opacity(0.45));
draw(P--Q--R--S--cycle,edge);
draw(T--U--V--W--cycle,edge);
draw(P--T,edge); draw(Q--U,edge); draw(R--V,edge); draw(S--W,edge);
label("solid",(5.6,0,-0.7),S);
label("$3$-form",(5.6,0,-1.2),S);
